"use client"

import { useMemo, type ComponentProps, type ReactNode } from "react"
import Link from "next/link"
import { usePathname } from "next/navigation"
import {
  FileText,
  FolderTree,
  Layers,
  LayoutDashboard,
  Package,
  Settings,
  ShoppingBag,
  Star,
  Users,
  type LucideIcon,
} from "lucide-react"

import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarRail,
} from "@/components/ui/sidebar"
import { AppLogo } from "@/components/admin/admin-shell/app-logo"

export interface NavItem {
  title: string
  href: string
  icon: LucideIcon
  badge?: string | number
}

export interface NavGroup {
  label: string
  items: NavItem[]
}

// ============================================================================
// Navigation Menu Configuration
// Group your sidebar items here. Easily add new groups and routes!
// ============================================================================
export const defaultNavGroups: NavGroup[] = [
  {
    label: "Overview",
    items: [
      {
        title: "Dashboard",
        href: "/admin",
        icon: LayoutDashboard,
      },
    ],
  },
  {
    label: "Catalog",
    items: [
      {
        title: "Products",
        href: "/admin/products",
        icon: Package,
      },
      {
        title: "Categories",
        href: "#",
        icon: FolderTree,
        badge: "Soon",
      },
    ],
  },
  {
    label: "Sales",
    items: [
      {
        title: "Orders",
        href: "#",
        icon: ShoppingBag,
        badge: "Soon",
      },
      {
        title: "Customers",
        href: "#",
        icon: Users,
        badge: "Soon",
      },
    ],
  },
  {
    label: "Content",
    items: [
      {
        title: "Articles",
        href: "#",
        icon: FileText,
        badge: "Soon",
      },
      {
        title: "Reviews",
        href: "#",
        icon: Star,
        badge: "Soon",
      },
    ],
  },
  {
    label: "System",
    items: [
      {
        title: "Settings",
        href: "/admin/settings",
        icon: Settings,
      },
      {
        title: "Placeholder Menu",
        href: "/placeholder",
        icon: Layers,
        badge: "Guide",
      },
    ],
  },
]

// Flattened fallback for backwards compatibility
export const defaultNavItems: NavItem[] = defaultNavGroups.flatMap((g) => g.items)

export interface AppSidebarProps extends ComponentProps<typeof Sidebar> {
  navGroups?: NavGroup[]
  navItems?: NavItem[]
  brand?: {
    name?: string
    imageSrc?: string
    description?: string
  }
  footerContent?: ReactNode
}

export function AppSidebar({
  navGroups,
  navItems,
  brand,
  footerContent,
  collapsible = "icon",
  className,
  ...props
}: AppSidebarProps) {
  const pathname = usePathname()

  // Resolve groups: prioritize navGroups, fallback to navItems wrapped in a single group, or defaultNavGroups
  const resolvedGroups: NavGroup[] = useMemo(() => {
    if (navGroups && navGroups.length > 0) return navGroups
    if (navItems && navItems.length > 0) {
      return [{ label: "Navigation", items: navItems }]
    }
    return defaultNavGroups
  }, [navGroups, navItems])

  const isItemActive = (href: string) => {
    if (href === "#" || href.startsWith("#") || href.startsWith("/#")) {
      return false
    }
    if (href === "/" || href === "/admin") {
      return pathname === "/" || pathname === "/admin"
    }
    if (pathname === href) return true
    if (href === "/admin/products" || href === "/products") {
      return (
        pathname === "/admin/products" ||
        pathname.startsWith("/admin/products/") ||
        pathname === "/products" ||
        pathname.startsWith("/products/")
      )
    }
    if (href === "/admin/settings" || href === "/settings") {
      return (
        pathname === "/admin/settings" ||
        pathname.startsWith("/admin/settings/") ||
        pathname === "/settings" ||
        pathname === "/profile" ||
        pathname.startsWith("/settings/")
      )
    }
    return pathname.startsWith(href)
  }

  return (
    <Sidebar
      collapsible={collapsible}
      className={cn("border-r", className)}
      {...props}
    >
      <SidebarHeader className="h-16 border-b px-4 flex flex-row items-center group-data-[collapsible=icon]:px-0 group-data-[collapsible=icon]:justify-center">
        <AppLogo
          name={brand?.name}
          description={brand?.description}
          imageSrc={brand?.imageSrc}
        />
      </SidebarHeader>

      <SidebarContent>
        {resolvedGroups.map((group) => (
          <SidebarGroup key={group.label}>
            <SidebarGroupLabel className="text-xs font-medium uppercase tracking-wider text-muted-foreground/70 group-data-[collapsible=icon]:hidden">
              {group.label}
            </SidebarGroupLabel>
            <SidebarGroupContent>
              <SidebarMenu>
                {group.items.map((item) => {
                  const Icon = item.icon
                  const active = isItemActive(item.href)

                  return (
                    <SidebarMenuItem key={`${item.title}-${item.href}`}>
                      <SidebarMenuButton
                        render={
                          <Link href={item.href} className="flex items-center gap-3">
                            <Icon className="size-4 shrink-0" />
                            <span className="truncate group-data-[collapsible=icon]:hidden">
                              {item.title}
                            </span>
                            {item.badge !== undefined && (
                              <Badge
                                variant={active ? "default" : "secondary"}
                                className="ml-auto text-[10px] px-1.5 py-0 h-4 min-w-4 justify-center group-data-[collapsible=icon]:hidden font-medium"
                              >
                                {item.badge}
                              </Badge>
                            )}
                          </Link>
                        }
                        isActive={active}
                        tooltip={item.title}
                        className={cn(
                          "transition-colors",
                          active && "font-medium"
                        )}
                      />
                    </SidebarMenuItem>
                  )
                })}
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        ))}
      </SidebarContent>

      {footerContent && (
        <SidebarFooter className="border-t p-4 group-data-[collapsible=icon]:p-2">
          {footerContent}
        </SidebarFooter>
      )}

      <SidebarRail />
    </Sidebar>
  )
}

"use client"

import { Fragment, type HTMLAttributes, type ReactNode } from "react"
import Link from "next/link"
import { usePathname } from "next/navigation"
import { Bell } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { SidebarTrigger } from "@/components/ui/sidebar"
import { ThemeToggle } from "./theme-toggle"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"

export interface AdminBreadcrumbItem {
  label: string
  href?: string
}

export interface AdminHeaderProps extends HTMLAttributes<HTMLElement> {
  breadcrumbs?: AdminBreadcrumbItem[]
  actions?: ReactNode
  userNav?: ReactNode
  notificationsCount?: number
  onNotificationsClick?: () => void
  showThemeToggle?: boolean
}

function generateDefaultBreadcrumbs(pathname: string): AdminBreadcrumbItem[] {
  const segments = pathname.split("/").filter(Boolean)
  if (segments.length === 0 || (segments.length === 1 && segments[0] === "admin")) {
    return [{ label: "Dashboard", href: "/admin" }]
  }

  const items: AdminBreadcrumbItem[] = [{ label: "Dashboard", href: "/admin" }]
  let accumulatedPath = ""

  segments.forEach((seg, idx) => {
    accumulatedPath += `/${seg}`
    if (seg === "admin") return // Skip 'admin' prefix as root dashboard already represents /admin
    const label = seg.charAt(0).toUpperCase() + seg.slice(1).replace(/-/g, " ")
    const isLast = idx === segments.length - 1
    items.push({
      label,
      href: isLast ? undefined : accumulatedPath,
    })
  })

  return items
}

export function AdminHeader({
  breadcrumbs,
  actions,
  userNav,
  notificationsCount = 2,
  onNotificationsClick,
  showThemeToggle = true,
  className,
  children,
  ...props
}: AdminHeaderProps) {
  const pathname = usePathname()
  const activeBreadcrumbs = breadcrumbs ?? generateDefaultBreadcrumbs(pathname || "/")

  return (
    <header
      className={cn(
        "sticky top-0 z-30 flex h-16 w-full items-center justify-between border-b bg-background px-6 transition-all",
        className
      )}
      {...props}
    >
      {/* Left: Sidebar trigger & clean breadcrumb */}
      <div className="flex items-center gap-3 min-w-0">
        <SidebarTrigger className="-ml-1" />
        <Breadcrumb>
          <BreadcrumbList>
            {activeBreadcrumbs.map((crumb, idx) => {
              const isLast = idx === activeBreadcrumbs.length - 1
              return (
                <Fragment key={`${crumb.label}-${idx}`}>
                  <BreadcrumbItem>
                    {isLast || !crumb.href ? (
                      <BreadcrumbPage>
                        {crumb.label}
                      </BreadcrumbPage>
                    ) : (
                      <BreadcrumbLink render={<Link href={crumb.href}>{crumb.label}</Link>} />
                    )}
                  </BreadcrumbItem>
                  {!isLast && <BreadcrumbSeparator />}
                </Fragment>
              )
            })}
          </BreadcrumbList>
        </Breadcrumb>
      </div>

      {/* Right: Actions, theme toggle, notifications, and userNav */}
      <div className="flex items-center gap-2">
        {actions}
        {children}

        {showThemeToggle && <ThemeToggle />}

        <Button
          variant="ghost"
          size="icon"
          className="relative size-9 text-muted-foreground hover:text-foreground"
          onClick={onNotificationsClick}
          aria-label="Notifications"
        >
          <Bell className="size-4" />
          {notificationsCount > 0 && (
            <span className="absolute top-2 right-2 size-2 rounded-full bg-primary ring-2 ring-background" />
          )}
        </Button>

        {userNav}
      </div>
    </header>
  )
}

"use client"

import { Moon, Sun } from "lucide-react"
import { useTheme } from "next-themes"

import { Button } from "@/components/ui/button"

export function ThemeToggle({ className }: { className?: string }) {
  const { setTheme, resolvedTheme } = useTheme()

  return (
    <Button
      type="button"
      variant="ghost"
      size="icon"
      className={className ?? "relative size-9 text-muted-foreground hover:text-foreground"}
      onClick={() => setTheme(resolvedTheme === "dark" ? "light" : "dark")}
      aria-label="Toggle theme"
    >
      <Sun className="size-4 rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0" />
      <Moon className="absolute size-4 rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100" />
      <span className="sr-only">Toggle theme</span>
    </Button>
  )
}

import type { HTMLAttributes, ReactNode } from "react"
import { cn } from "@/lib/utils"

export interface PageHeaderProps extends HTMLAttributes<HTMLDivElement> {
  title: string
  description?: string
  children?: ReactNode
}

export function PageHeader({
  title,
  description,
  children,
  className,
  ...props
}: PageHeaderProps) {
  return (
    <div
      className={cn(
        "flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between",
        className
      )}
      {...props}
    >
      <div className="space-y-1">
        <h1 className="text-2xl font-semibold tracking-tight text-foreground">
          {title}
        </h1>
        {description && (
          <p className="text-sm text-muted-foreground">{description}</p>
        )}
      </div>
      {children && (
        <div className="flex flex-wrap items-center gap-2">{children}</div>
      )}
    </div>
  )
}

import type { HTMLAttributes } from "react"
import { TrendingDown, TrendingUp, type LucideIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"

export interface StatCardProps extends HTMLAttributes<HTMLDivElement> {
  title: string
  value: string | number
  description?: string
  icon?: LucideIcon
  trend?: {
    value: string
    positive: boolean
  }
}

export function StatCard({
  title,
  value,
  description,
  icon: Icon,
  trend,
  className,
  ...props
}: StatCardProps) {
  return (
    <Card className={cn("@container/card relative", className)} {...props}>
      <CardHeader className="relative space-y-1 pb-2">
        <div className="flex items-center justify-between">
          <CardDescription className="text-sm font-medium text-muted-foreground">
            {title}
          </CardDescription>
          {Icon && (
            <div className="flex size-7 items-center justify-center rounded-md text-muted-foreground">
              <Icon className="size-4" />
            </div>
          )}
        </div>
        <CardTitle className="text-2xl font-semibold tracking-tight tabular-nums">
          {value}
        </CardTitle>
      </CardHeader>
      {(description || trend) && (
        <CardContent className="pt-0 text-xs">
          <div className="flex items-center gap-1.5">
            {trend && (
              <Badge
                variant="outline"
                className={cn(
                  "gap-1 rounded-md px-1.5 py-0.5 text-[11px] font-normal border-transparent bg-muted/60",
                  trend.positive
                    ? "text-emerald-600 dark:text-emerald-400"
                    : "text-rose-600 dark:text-rose-400"
                )}
              >
                {trend.positive ? (
                  <TrendingUp className="size-3" />
                ) : (
                  <TrendingDown className="size-3" />
                )}
                {trend.value}
              </Badge>
            )}
            {description && (
              <span className="text-muted-foreground truncate">{description}</span>
            )}
          </div>
        </CardContent>
      )}
    </Card>
  )
}

"use client"

import type { HTMLAttributes } from "react"
import Link from "next/link"

import { cn } from "@/lib/utils"

// ============================================================================
// Brand Logo Configuration
// Update this path to change the logo across your entire admin application.
// Place your logo file in /public (e.g. /public/logo.svg, /public/brand.png).
// ============================================================================
export const DEFAULT_LOGO_IMAGE = "/logo.svg"
export const DEFAULT_BRAND_NAME = "Admin Portal"
export const DEFAULT_BRAND_DESCRIPTION = "Design System Registry"

export interface AppLogoProps extends HTMLAttributes<HTMLDivElement> {
  imageSrc?: string
  name?: string
  description?: string
  href?: string | null
  collapsed?: boolean
  size?: "sm" | "default" | "lg"
}

export function AppLogo({
  imageSrc = DEFAULT_LOGO_IMAGE,
  name = DEFAULT_BRAND_NAME,
  description = DEFAULT_BRAND_DESCRIPTION,
  href = "/admin",
  collapsed = false,
  size = "default",
  className,
  ...props
}: AppLogoProps) {
  const content = (
    <div
      className={cn(
        "flex items-center gap-3 select-none transition-all",
        collapsed && "justify-center",
        className
      )}
      {...props}
    >
      {/* Brand Logo Image (Maintained in this component) */}
      <div
        className={cn(
          "relative flex shrink-0 items-center justify-center rounded-lg overflow-hidden transition-transform",
          size === "sm" && "size-7 rounded-md",
          size === "default" && "size-9",
          size === "lg" && "size-10"
        )}
      >
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src={imageSrc}
          alt={name}
          className="size-full object-contain"
          loading="eager"
        />
      </div>

      {/* Brand Text Header */}
      {!collapsed && (
        <div className="flex flex-col overflow-hidden text-left leading-tight group-data-[collapsible=icon]:hidden">
          <span className="truncate text-sm font-medium tracking-tight text-foreground">
            {name}
          </span>
          {description && (
            <span className="truncate text-xs text-muted-foreground">
              {description}
            </span>
          )}
        </div>
      )}
    </div>
  )

  if (href) {
    return (
      <Link
        href={href}
        className="inline-flex focus:outline-hidden focus-visible:ring-2 focus-visible:ring-ring rounded-lg"
      >
        {content}
      </Link>
    )
  }

  return content
}

